-- Explicações por artigo — Lei das Contravenções Penais (Decreto-Lei nº 3.688, de 1941). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se às contravenções as regras gerais do Código Penal, sempre que a Lei das Contravenções Penais não disponha de modo diverso.', '["Regras gerais do Código Penal se aplicam às contravenções.","A Lei especial prevalece quando dispuser de forma diferente."]'::jsonb, '["Contravenção é infração penal de menor gravidade; o Código Penal vale subsidiariamente."]'::jsonb, 'Na falta de regra própria, a prescrição da contravenção segue o Código Penal.', '["Assertiva que afasta qualquer regra geral do Código Penal das contravenções erra: ela vale quando a lei não dispuser de modo diverso."]'::jsonb, '[{"termo":"Contravenção","significado":"Infração penal menos grave que o crime, punida com prisão simples ou multa."}]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'contravencoes' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

