insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a existência da contravenção, basta a ação ou omissão voluntária. Deve-se, porém, ter em conta o dolo ou a culpa, se a lei fizer depender de um ou de outra qualquer efeito jurídico.', '["Basta a ação ou omissão voluntária.","Dolo ou culpa só importam quando a lei lhes atribuir efeito."]'::jsonb, '["Em regra, a contravenção dispensa a análise de dolo ou culpa."]'::jsonb, 'Quem solta balão aceso em área urbana responde pela ação voluntária, ainda que sem querer o dano.', '["Assertiva que exige sempre dolo específico nas contravenções erra: basta a conduta voluntária."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
