insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas principais das contravenções são a prisão simples e a multa.', '["Prisão simples.","Multa."]'::jsonb, '["Não existe reclusão nem detenção para contravenções."]'::jsonb, 'A pena de uma contravenção pode ser apenas a multa.', '["Assertiva que prevê reclusão para contravenções erra: as penas são prisão simples e multa."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
