insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pena de prisão simples deve ser cumprida, sem rigor penitenciário, em estabelecimento especial ou seção especial de prisão comum, em regime semiaberto ou aberto. O condenado fica sempre separado dos condenados a reclusão ou detenção. O trabalho é facultativo se a pena aplicada não exceder quinze dias.', '["Sem rigor penitenciário.","Regime semiaberto ou aberto.","Separação dos condenados a reclusão ou detenção.","Trabalho facultativo se a pena não exceder quinze dias."]'::jsonb, '["Prisão simples NUNCA vai ao regime fechado."]'::jsonb, 'O condenado por contravenção cumpre pena em seção separada dos condenados por crime.', '["Assertiva que admite regime fechado para a prisão simples erra: apenas semiaberto ou aberto."]'::jsonb, '[{"termo":"Prisão simples","significado":"Pena das contravenções, cumprida sem rigor penitenciário."}]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'contravencoes' and u.unit_key = 'art-6'
