insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verifica-se a reincidência quando o agente pratica uma contravenção depois de passar em julgado a sentença que o tenha condenado, no Brasil ou no estrangeiro, por qualquer crime, ou, no Brasil, por motivo de contravenção.', '["Contravenção após condenação anterior por crime, no Brasil ou no exterior.","Ou após condenação por contravenção no Brasil."]'::jsonb, '["Crime anterior (qualquer, inclusive no exterior) + contravenção nova = reincidência.","Contravenção anterior só conta se for no Brasil."]'::jsonb, 'Quem foi condenado por furto e depois comete contravenção é reincidente.', '["Assertiva que não considera reincidente quem comete contravenção após condenação por crime erra."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'contravencoes' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

