insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A multa converte-se em prisão simples, conforme o Código Penal sobre conversão de multa em detenção. Se a multa é a única pena cominada, a conversão em prisão simples faz-se entre os limites de quinze dias e três meses.', '["Multa convertida em prisão simples.","Multa como única pena: conversão entre quinze dias e três meses."]'::jsonb, '["ATUALIZAÇÃO: lei posterior do Código Penal vedou a conversão da multa em prisão; consulte a vigência desta regra."]'::jsonb, 'A regra original previa converter a multa não paga em prisão simples.', '["Assertiva que mantém hoje a conversão da multa em prisão simples sem ressalvas erra: houve alteração legislativa."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'contravencoes' and u.unit_key = 'art-9'
