insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A duração da pena de prisão simples não pode, em caso algum, ser superior a cinco anos, nem a importância das multas ultrapassar cinquenta contos.', '["Limite da prisão simples: cinco anos.","Limite histórico das multas expresso em contos de réis."]'::jsonb, '["ATUALIZAÇÃO: o limite geral de cumprimento de pena é de quarenta anos no Código Penal; confira os limites aplicáveis."]'::jsonb, 'Nenhuma prisão simples pode passar de cinco anos.', '["Assertiva que fixa em dez anos o limite da prisão simples erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
