select u.id, u.content_sha256, 'Desde que reunidas as condições legais, o juiz pode suspender, por tempo não inferior a um ano nem superior a três, a execução da pena de prisão simples, bem como conceder livramento condicional.', '["Suspensão condicional (sursis) por um a três anos.","Livramento condicional."]'::jsonb, '["Sursis da contravenção: de um a três anos."]'::jsonb, 'O juiz suspende a pena de prisão simples por dois anos, mediante condições.', '["Assertiva que proíbe o sursis nas contravenções erra."]'::jsonb, '[{"termo":"Sursis","significado":"Suspensão condicional da execução da pena."}]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
