insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas acessórias são a publicação da sentença e as interdições de direitos: a incapacidade temporária para profissão ou atividade que dependa de habilitação, licença ou autorização do poder público, e a suspensão dos direitos políticos. Incorre na primeira, por um mês a dois anos, o condenado por contravenção cometida com abuso de profissão ou atividade, ou com infração de dever a ela inerente. Incorre na segunda o condenado a pena privativa de liberdade, enquanto dure a execução da pena ou da medida de segurança detentiva.', '["Publicação da sentença.","Incapacidade temporária para profissão: um mês a dois anos.","Suspensão dos direitos políticos durante a pena privativa de liberdade."]'::jsonb, '["ATUALIZAÇÃO: o sistema de penas acessórias foi reformado pela reforma da Parte Geral do Código Penal; verifique a vigência."]'::jsonb, 'O profissional que comete contravenção com abuso da profissão pode ficar um mês a dois anos impedido de exercê-la.', '["Assertiva que prevê a perda definitiva da profissão como pena acessória erra: a interdição é de um mês a dois anos."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'contravencoes' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

