insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trazer consigo arma fora de casa ou de dependência desta, sem licença da autoridade: prisão simples de quinze dias a seis meses, ou multa, ou ambas. A pena é aumentada de um terço até a metade se o agente já foi condenado, em sentença irrecorrível, por violência contra pessoa. Incorre em pena menor quem, possuindo arma ou munição, deixa de fazer comunicação ou entrega à autoridade quando a lei determina, permite que alienado menor de 18 anos ou pessoa inexperiente a tenha consigo ou omite cautelas para impedir que dela se apodere facilmente.', '["Porte de arma fora de casa sem licença.","Aumento de um terço até a metade para condenado por violência.","Omissão de comunicação, empréstimo a inexperiente e falta de cautela."]'::jsonb, '["ATUALIZAÇÃO: o porte ilegal de arma de fogo é hoje crime do Estatuto do Desarmamento; este artigo ficou restrito a outras armas."]'::jsonb, 'Portar arma de fogo na rua, sem licença, é hoje crime do Estatuto do Desarmamento.', '["Assertiva que aplica o art. 19 ao porte de arma de fogo hoje erra: o Estatuto trata o fato como crime."]'::jsonb, '[]'::jsonb, '["Estatuto do Desarmamento, art. 14"]'::jsonb, 'under_review', 'claude'
