insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Jogo de azar: estabelecer ou explorar jogo de azar em lugar público ou acessível ao público, mediante pagamento de entrada ou sem ele: prisão simples de três meses a um ano, e multa, com perda dos móveis e objetos de decoração do local. A pena é aumentada de um terço se há empregado ou participante menor de dezoito anos. Quem é encontrado a participar do jogo, ainda que pela internet ou outro meio, como ponteiro ou apostador, incorre em multa de R$ 2.000,00 a R$ 200.000,00. São jogos de azar aqueles em que o ganho e a perda dependem exclusiva ou principalmente da sorte, as apostas em corrida de cavalos fora de local autorizado e as apostas em qualquer outra competição esportiva. Equiparam-se a lugar acessível ao público a casa particular com jogo habitual de pessoas fora da família, o hotel ou casa coletiva, a sede de sociedade ou associação e o estabelecimento destinado ao jogo.', '["Explorar jogo de azar em lugar público ou acessível ao público.","Prisão simples de três meses a um ano e multa.","Aumento de um terço se houver menor de dezoito anos.","Multa ao participante (ponteiro ou apostador), inclusive pela internet.","Conceito de jogo de azar e lugares equiparados."]'::jsonb, '["ATUALIZAÇÃO: a multa do §2º e o alcance à internet foram incluídos por lei posterior; o regime de apostas de quota fixa é regulado por lei própria, que autoriza operadores licenciados.","Jogos de azar continuam contravenção, salvo atividades autorizadas em lei."]'::jsonb, 'Manter uma casa de jogo de azar aberta ao público é a contravenção do art. 50.', '["Assertiva que exige cobrança de entrada para configurar a contravenção erra: ocorre mediante pagamento de entrada ou sem ele."]'::jsonb, '[{"termo":"Jogo de azar","significado":"Jogo em que o ganho ou a perda dependem principalmente da sorte."}]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'contravencoes' and u.unit_key = 'art-50'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Promover ou fazer extrair loteria, sem autorização legal: prisão simples de seis meses a dois anos, e multa, com perda dos móveis do local. Incorre na mesma pena quem guarda, vende ou expõe à venda, tem sob sua guarda para venda, introduz ou tenta introduzir na circulação bilhete de loteria não autorizada. Loteria é toda operação que, mediante distribuição de bilhetes, listas, cupões, vales, sinais ou meios análogos, faz depender de sorteio a obtenção de prêmio em dinheiro ou bens. Não se compreendem os sorteios autorizados em legislação especial.', '["Promover ou extrair loteria sem autorização.","Venda e circulação de bilhetes de loteria não autorizada.","Conceito de loteria.","Sorteios autorizados em lei especial ficam fora."]'::jsonb, '["Loteria autorizada em lei não é contravenção."]'::jsonb, 'Organizar uma rifa clandestina com venda de bilhetes é contravenção.', '["Assertiva que alcança também os sorteios autorizados em legislação especial erra: eles ficam excluídos."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'contravencoes' and u.unit_key = 'art-51'
