on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta lei entrará em vigor no dia 1º de janeiro de 1942.', '["Vigência em 1º de janeiro de 1942."]'::jsonb, '["Lei histórica, de 1941, com muitos artigos revogados ou superados."]'::jsonb, 'A lei foi publicada em 1941 e passou a valer em 1942.', '["Assertiva que prevê vigência imediata na data da publicação erra: começou em 1º de janeiro de 1942."]'::jsonb, '[]'::jsonb, '["Art. 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'contravencoes' and u.unit_key = 'art-72'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();
